// runPatch mirrors steps 2-5 of patchContents without touching the disk:
// verify anchors, drop entries whose old_string equals new_string, locate the
// spans, apply them back to front, and refuse a result that empties the file.
// It returns the patched content, whether every entry was a no-op, and the
// first error. Keep it in step with patchContents when that flow changes.
func runPatch(content string, entries []patchContent) (string, bool, error) {
	entries = slices.Clone(entries)
	if err := verifyAnchors(content, entries, "test.go"); err != nil {
		return "", false, err
	}

	pending := make([]patchContent, 0, len(entries))
	for i, one := range entries {
		if one.OldString == one.NewString {
			continue
		}
		one.index = i
		pending = append(pending, one)
	}
	if len(pending) == 0 {
		return content, true, nil
	}

	spans, err := planTargets(content, pending, "test.go")
	if err != nil {
		return "", false, err
	}

	oldContent := content
	for _, span := range slices.Backward(spans) {
		content = content[:span.start] + span.text + content[span.end:]
	}
	if strings.TrimSpace(content) == "" && strings.TrimSpace(oldContent) != "" {
		return "", false, errLeftEmpty
	}
	return content, false, nil
}

