// TestPlanTargetsMissingAnchor guards planTargets when a caller skips
// verifyAnchors: a missing anchor must return an error carrying the original
// index instead of panicking on at[:1].
func TestPlanTargetsMissingAnchor(t *testing.T) {
	_, err := planTargets("alpha\n", []patchContent{{OldString: "gamma", NewString: "GAMMA", index: 2}}, "test.go")
	if err == nil || !strings.Contains(err.Error(), "patch_contents[2]") {
		t.Fatalf("planTargets() error = %v, want Internal error for patch_contents[2]", err)
	}
}
